bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,pass=readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim();
const url='postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(pass)+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const p=new pg.Pool({connectionString:url,max:1,connectionTimeoutMillis:5000});
try {
 const l=await p.query("SELECT listing_id,revision,status,price_stars,sample_duration_seconds,thumbnail_file_id=paid_video_file_id AS thumb_is_main,sample_file_id=paid_video_file_id AS sample_is_main,thumbnail_file_id=sample_file_id AS thumb_is_sample FROM videobot_listings WHERE listing_id=$1",['389558ba-a38b-42a1-b92e-e98143df3e2d']);
 const r=await p.query("SELECT delivery_key,status,topic_id,free_message_ids,paid_message_id FROM videobot_post_receipts WHERE listing_id=$1 ORDER BY revision",['389558ba-a38b-42a1-b92e-e98143df3e2d']);
 for(const x of l.rows)console.log('LISTING_SAFE='+JSON.stringify(x));
 for(const x of r.rows)console.log('RECEIPT_SAFE='+JSON.stringify(x));
 console.log('THREAD_ENV='+e.VIDEOBOT_VIDEO_SALE_THREAD_ID);
}finally{await p.end()}
NODE
echo USERBOT_RESIDENT_ACTIVE="$(systemctl --user is-active gace-userbot-verify.service || true)"
echo USERBOT_IPC_FILES="$(find /home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot -maxdepth 3 -type f \( -iname '*ipc*' -o -iname '*verify*client*' \) 2>/dev/null | head -n 8 | wc -l)"
